App.my.BILLS = 'bills';
App.my.GOODS = 'goods';
App.my.cur = () => { const b = App.load('current', null); return b && Array.isArray(b.lines) ? b : { who: '', lines: [] }; };
App.my.setCur = (b) => App.save('current', b);
App.my.total = (b) => (b.lines || []).reduce((s, l) => s + (Number(l.qty) || 0) * (Number(l.price) || 0), 0);
App.my.q = (x) => (Number.isInteger(Number(x)) ? App.n(x) : App.n(x, 2));
App.my.text = (b) => ['🧾 బిల్లు' + (b.no ? ' #' + b.no : '') + (b.who ? ' · ' + b.who : ''), App.date(b.date || App.today())]
  .concat((b.lines || []).map((l) => l.name + '  ' + App.my.q(l.qty) + ' × ' + App.rs(l.price) + ' = ' + App.rs(l.qty * l.price)))
  .concat(['మొత్తం: ' + App.rs(App.my.total(b))]).join('\n');
App.my.html = (b) => `<h2>బిల్లు${b.no ? ' #' + b.no : ''}</h2><p>${b.who ? App.esc(b.who) + ' · ' : ''}${App.date(b.date || App.today())}</p>`
  + '<table><tr><th>సరుకు</th><th>ఎన్ని</th><th>ధర</th><th>మొత్తం</th></tr>'
  + (b.lines || []).map((l) => `<tr><td>${App.esc(l.name)}</td><td class="n">${App.my.q(l.qty)}</td><td class="n">${App.rs(l.price)}</td><td class="n">${App.rs(l.qty * l.price)}</td></tr>`).join('')
  + `<tr><th colspan="3">మొత్తం</th><th class="n">${App.rs(App.my.total(b))}</th></tr></table>`;
App.my.share = async (b) => { try { await App.share(App.my.text(b)); } catch (e) { App.toast('షేర్ కాలేదు'); } };
App.my.pdf = async (b) => { try { await App.pdf('బిల్లు' + (b.no ? ' ' + b.no : ''), App.my.html(b)); } catch (e) { App.toast('PDF కాలేదు'); } };
App.my.addLine = (name, qty, price) => {
  const b = App.my.cur();
  b.lines.push({ name: String(name).slice(0, 60), qty, price });
  App.my.setCur(b);
  if (App.my.drawBill) App.my.drawBill();
};
App.onJarvis('add-item', (d) => {
  const name = String(d.name || '').trim().slice(0, 60);
  if (!name) return 'సరుకు పేరు లేదు; ఏమీ చేర్చలేదు';
  const g = App.items(App.my.GOODS).find((x) => String(x.name).toLowerCase() === name.toLowerCase());
  const qty = Number(d.qty) > 0 ? Number(d.qty) : 1;
  const price = d.price != null && d.price !== '' && Number(d.price) >= 0 ? Number(d.price) : g ? Number(g.price) : NaN;
  if (!(price >= 0)) return name + ' ధర తెలియదు; ధరతో చెప్పండి';
  App.my.addLine(name, qty, price);
  return name + ' ' + App.my.q(qty) + ' × ' + App.rs(price) + ' బిల్లులో చేర్చాను';
});

App.onShow('home', () => {
  const all = App.items(App.my.BILLS).slice().sort((a, b) => b.at - a.at), today = App.today(), mk = App.monthKey(new Date());
  App.text('#home-today', App.rs(all.filter((b) => b.date === today).reduce((s, b) => s + App.my.total(b), 0)));
  App.text('#home-month', App.rs(all.filter((b) => App.monthKey(b.date) === mk).reduce((s, b) => s + App.my.total(b), 0)));
  const c = App.my.cur();
  App.text('#home-new', c.lines.length ? '✏️ సగం బిల్లు కొనసాగించు (' + c.lines.length + ' సరుకులు)' : '➕ కొత్త బిల్లు');
  App.set('#home-list', all.length ? '<div class="list">' + all.slice(0, 100).map((b) => `
    <div class="item" data-id="${App.esc(b.id)}"><div class="ic">🧾</div>
      <div class="w"><div class="t">#${App.esc(b.no)} ${App.esc(b.who || '')}</div><div class="s">${App.date(b.date, 'short')} · ${(b.lines || []).length} సరుకులు</div></div>
      <div class="r">${App.rs(App.my.total(b))}</div></div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🧾</div>ఇంకా బిల్లులు లేవు. ➕ నొక్కి మొదలుపెట్టండి.</div>');
});
App.click('#home-new', () => App.go('bill'));
App.click('#home-list .item', (ev, el) => App.go('view', App.find(App.my.BILLS, el.dataset.id)));

App.my.drawBill = () => {
  const b = App.my.cur();
  App.set('#bill-lines', b.lines.length ? '<div class="list">' + b.lines.map((l, i) => `
    <div class="item" data-i="${i}"><div class="w"><div class="t">${App.esc(l.name)}</div><div class="s">${App.my.q(l.qty)} × ${App.rs(l.price)}</div></div>
      <div class="r">${App.rs(l.qty * l.price)}</div></div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🛒</div>పైన సరుకు రాసి ➕ నొక్కండి.</div>');
  App.text('#bill-total', App.rs(App.my.total(b)));
};
App.onShow('bill', () => {
  const b = App.my.cur(), goods = App.items(App.my.GOODS);
  App.val('#bill-who', b.who || '');
  App.set('#bill-goods', goods.map((g) => `<option value="${App.esc(g.name)}"></option>`).join(''));
  App.set('#bill-quick', goods.slice(0, 12).map((g) => `<button class="chip" data-id="${App.esc(g.id)}">${App.esc(g.name)} ${App.rs(g.price)}</button>`).join(''));
  App.my.drawBill();
});
App.on('#bill-who', 'change', () => { const b = App.my.cur(); b.who = App.val('#bill-who').slice(0, 60); App.my.setCur(b); });
App.on('#bill-name', 'change', () => {
  const g = App.items(App.my.GOODS).find((x) => x.name === App.val('#bill-name'));
  if (g && !App.val('#bill-price')) App.val('#bill-price', g.price);
});
App.click('#bill-add', () => {
  const name = App.val('#bill-name'), qty = Number(App.val('#bill-qty') || 1), price = Number(App.val('#bill-price'));
  if (!name) { App.toast('సరుకు పేరు రాయండి'); return; }
  if (!(qty > 0)) { App.toast('ఎన్ని అనేది సరిగా రాయండి'); return; }
  if (App.val('#bill-price') === '' || !(price >= 0)) { App.toast('ధర రాయండి'); return; }
  App.my.addLine(name, qty, price);
  App.beep('tap');
  App.val('#bill-name', ''); App.val('#bill-qty', ''); App.val('#bill-price', '');
});
App.click('#bill-quick .chip', (ev, el) => {
  const g = App.find(App.my.GOODS, el.dataset.id);
  if (g) { App.my.addLine(g.name, 1, Number(g.price) || 0); App.beep('tap'); }
});
App.click('#bill-lines .item', async (ev, el) => {
  const b = App.my.cur(), i = Number(el.dataset.i), l = b.lines[i];
  if (!l) return;
  if (await App.ask(l.name + ' బిల్లులోంచి తీసేయాలా?', 'తీసేయి', 'వద్దు')) { b.lines.splice(i, 1); App.my.setCur(b); App.my.drawBill(); }
});
App.click('#bill-save', () => {
  const b = App.my.cur();
  if (!b.lines.length) { App.toast('బిల్లులో సరుకులు లేవు'); return; }
  const no = (Number(App.load('billNo', 0)) || 0) + 1;
  App.save('billNo', no);
  const saved = App.add(App.my.BILLS, { no, who: b.who || '', lines: b.lines, date: App.today() });
  App.my.setCur({ who: '', lines: [] });
  App.beep('done');
  App.toast('బిల్లు #' + no + ' దాచాను');
  App.back();
  App.go('view', saved);
});
App.click('#bill-share', () => { const b = App.my.cur(); if (!b.lines.length) { App.toast('బిల్లులో సరుకులు లేవు'); return; } App.my.share(b); });
App.click('#bill-pdf', () => { const b = App.my.cur(); if (!b.lines.length) { App.toast('బిల్లులో సరుకులు లేవు'); return; } App.my.pdf(b); });

App.onShow('view', (b) => {
  App.my.viewing = b && b.id ? b.id : null;
  if (!App.my.viewing) { App.set('#view-body', '<div class="muted">ఏ బిల్లూ ఎంచుకోలేదు</div>'); return; }
  App.title('బిల్లు #' + b.no);
  App.set('#view-body', App.my.html(b));
});
const shown = () => (App.my.viewing ? App.find(App.my.BILLS, App.my.viewing) : null);
App.click('#view-share', () => { const b = shown(); if (b) App.my.share(b); });
App.click('#view-pdf', () => { const b = shown(); if (b) App.my.pdf(b); });
App.click('#view-copy', async () => { const b = shown(); if (!b) return; try { await App.copy(App.my.text(b)); } catch (e) { App.toast('కాపీ కాలేదు'); } });
App.click('#view-del', async () => {
  const b = shown();
  if (!b) return;
  if (await App.ask('బిల్లు #' + b.no + ' తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.BILLS, b.id); App.my.viewing = null; App.toast('తీసేశాను'); App.back(); }
});

App.onShow('goods', () => {
  const g = App.items(App.my.GOODS).slice().sort((a, b) => String(a.name).localeCompare(String(b.name)));
  App.set('#goods-list', g.length ? '<div class="list">' + g.map((x) => `
    <div class="item" data-id="${App.esc(x.id)}"><div class="ic">📦</div><div class="w"><div class="t">${App.esc(x.name)}</div></div><div class="r">${App.rs(x.price)}</div></div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">📦</div>ఇంకా సరుకులు లేవు. + నొక్కి రాయండి.</div>');
});
App.my.editGood = async (x) => {
  const f = await App.form(x ? 'సరుకు మార్చండి' : 'కొత్త సరుకు', [
    { key: 'name', label: 'పేరు', need: true, value: x ? x.name : '' },
    { key: 'price', label: 'ధర (₹)', type: 'number', need: true, value: x ? x.price : '' }], 'దాచు');
  if (!f) return;
  if (!(f.price >= 0)) { App.toast('ధర సరిగా రాయండి'); return; }
  const rec = { name: String(f.name).slice(0, 60), price: f.price };
  if (x) App.update(App.my.GOODS, x.id, rec); else App.add(App.my.GOODS, rec);
  App.toast('దాచాను');
  App.refresh();
};
App.click('#goods-add', () => App.my.editGood(null));
App.click('#goods-list .item', async (ev, el) => {
  const x = App.find(App.my.GOODS, el.dataset.id);
  if (!x) return;
  const i = await App.pick(x.name, ['✏️ మార్చు', '🗑️ తీసేయి']);
  if (i === 0) await App.my.editGood(x);
  if (i === 1 && await App.ask(x.name + ' తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.GOODS, x.id); App.refresh(); }
});
